import csv
import io
import re


def parse_csv(raw_csv: str):
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=",", quotechar='"')

    records = []
    for record in reader:
        if not record or all(value == "" for value in record):
            continue
        if record[0].lstrip().startswith("#"):
            continue
        records.append([str(value) for value in record])

    if not records:
        return {"columns": ["column_1", "column_2", "column_3", "column_4"], "rows": []}

    numeric = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$")
    first = records[0]
    has_header = not all(numeric.match(value.strip()) for value in first)

    if has_header:
        columns = [value if value else f"column_{i + 1}" for i, value in enumerate(first)]
        data = records[1:]
    else:
        columns = [f"column_{i + 1}" for i in range(4)]
        data = records

    width = max(4, len(columns), max((len(row) for row in data), default=0))
    while len(columns) < width:
        columns.append(f"column_{len(columns) + 1}")

    rows = [row + [""] * (width - len(row)) for row in data]
    return {"columns": columns, "rows": rows}
